using System.Net;
using System.Text.Json;
using System.Text.Json.Nodes;
using Microsoft.AspNetCore.DataProtection;
public static class SmsChecks
{
    static void Check(bool ok,string name){if(!ok)throw new InvalidOperationException("SMS check failed: "+name);}
    static void Reject(Action action,string name){bool failed=false;try{action();}catch(ArgumentException){failed=true;}Check(failed,name);}
    sealed class FakeHandler:HttpMessageHandler{public string Response="{\"code\":\"00\"}";public int Calls;protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage req,CancellationToken ct){Calls++;return Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent(Response)});}}
    public static void Run(){var temp=Path.Combine(Path.GetTempPath(),"inokskar-sms-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(temp);try{var b=WebApplication.CreateBuilder();b.Configuration["Storage:Path"]=temp;var protection=DataProtectionProvider.Create(new DirectoryInfo(Path.Combine(temp,"keys")));var settings=new SmsSettingsStore(b.Environment,b.Configuration,protection);var customers=new CustomerDirectory(b.Environment,b.Configuration);var codes=new SmsCodes(b.Environment,b.Configuration);
        Check(!settings.Active,"disabled by default");Check(!SmsPages.AddOptions("<head></head><form></form>",false,"register").Contains("Telefonla"),"inactive options absent");Check(SmsPages.AddOptions("<head></head><form></form>",true,"register").Contains("Telefonla üye ol"),"active option");
        foreach(var phone in new[]{"5421234567","05421234567","905421234567","+90 (542) 123-45-67","00905421234567"})Check(SmsPhone.Normalize(phone)=="905421234567","normalization");Reject(()=>SmsPhone.Normalize("invalid"),"invalid phone");
        var old=customers.Create("Eski Üye","sms-old@example.invalid","Old-password-123","05421234567");Check(customers.ByPhone("5421234567")?.Id==old.Id,"legacy email lookup");Reject(()=>customers.Create("Tekrar","other@example.invalid","Other-password-123","+905421234567"),"duplicate phone");var pair=codes.Create(old.Phone,"recover",old);Reject(()=>codes.Consume(pair.Challenge.Id,pair.Code,"recover",_=>{}),"undelivered code");codes.Delivered(pair.Challenge.Id);Reject(()=>codes.Consume(pair.Challenge.Id,pair.Code,"register",_=>{}),"purpose mismatch");Reject(()=>codes.Consume(pair.Challenge.Id,pair.Code=="000000"?"000001":"000000","recover",_=>{}),"wrong code");Check(!File.ReadAllText(Path.Combine(temp,"sms-codes.json")).Contains(pair.Code),"code stored hashed");codes.Consume(pair.Challenge.Id,pair.Code,"recover",c=>customers.ResetPasswordByPhone(c.CustomerId,c.Phone,c.Stamp,"New-password-123"));Reject(()=>codes.Consume(pair.Challenge.Id,pair.Code,"recover",_=>{}),"single use");Check(customers.ById(old.Id)!.SecurityStamp!=old.SecurityStamp,"session revocation");Check(customers.Verify(old.Email,"New-password-123")!=null&&customers.VerifyPhone("5421234567","New-password-123")?.Id==old.Id,"same account email and phone");Reject(()=>codes.Create(old.Phone,"recover",old),"cooldown");
        var phoneOnly=customers.CreateByPhone("Telefon Üyesi","5531234567","Phone-password-123");Check(phoneOnly.Email==""&&phoneOnly.PhoneVerified&&CustomerDirectory.Principal(phoneOnly).Identity!.Name==phoneOnly.Phone,"phone identity");Reject(()=>customers.ResetPasswordByEmail("","bad-password-123"),"empty email rejected");customers.UpdateProfile(phoneOnly.Id,new JsonObject{["phone"]="5541234567"});Check(!customers.ById(phoneOnly.Id)!.PhoneVerified,"changed phone unverified");
        var expired=codes.Create("5551234567","register");codes.Delivered(expired.Challenge.Id);var path=Path.Combine(temp,"sms-codes.json");var rows=JsonNode.Parse(File.ReadAllText(path))!.AsArray();rows.Last()!["Expires"]=DateTimeOffset.UtcNow.AddMinutes(-1);File.WriteAllText(path,rows.ToJsonString());Reject(()=>codes.Consume(expired.Challenge.Id,expired.Code,"register",_=>{}),"expiry");var limit=codes.Create("5561234567","register");codes.Delivered(limit.Challenge.Id);for(int i=0;i<5;i++)Reject(()=>codes.Consume(limit.Challenge.Id,limit.Code=="000000"?"000001":"000000","register",_=>{}),"bad attempt");Reject(()=>codes.Consume(limit.Challenge.Id,limit.Code,"register",_=>{}),"attempt limit");
        Reject(()=>SmsGateway.ValidateEndpoint("http://example.com/send"),"HTTPS");Reject(()=>SmsGateway.ValidateEndpoint("https://127.0.0.1/send"),"localhost");Check(!SmsGateway.IsPublic(IPAddress.Parse("10.0.0.1"))&&!SmsGateway.IsPublic(IPAddress.Parse("::ffff:192.168.1.1")),"private DNS");
        foreach(var p in SmsSettingsStore.Presets){settings.Save(new JsonObject{["id"]=p.Id,["name"]=p.Name,["endpoint"]=p.Endpoint,["auth"]=p.Auth,["username"]="ACtest-user",["secret"]="TEST-secret-sentinel",["sender"]="INOKSKAR",["successPath"]=p.SuccessPath,["successValue"]=p.SuccessValue,["enabled"]=true});Check(settings.Active,"provider active");Check(!File.ReadAllText(Path.Combine(temp,"sms-settings.json")).Contains("TEST-secret-sentinel")&&!JsonSerializer.Serialize(settings.PublicSettings()).Contains("TEST-secret-sentinel"),"secret encrypted and redacted");var fake=new FakeHandler{Response=p.Id switch{"iletimerkezi"=>"{\"response\":{\"status\":{\"code\":200}}}","verimor"=>"12345","twilio"=>"{\"sid\":\"SMtest\"}",_=>"{\"code\":\"00\"}"}};var gateway=new SmsGateway(settings,fake);gateway.Send("5421234567","Türkçe mesaj").GetAwaiter().GetResult();Check(fake.Calls==1,"provider send accepted");fake.Response=p.Id=="verimor"?"ERROR":"{\"code\":\"70\"}";bool failed=false;try{gateway.Send("5421234567","test").GetAwaiter().GetResult();}catch(InvalidOperationException){failed=true;}Check(failed,"provider application error");settings.Save(new JsonObject{["disableOnly"]=true});failed=false;try{gateway.Send("5421234567","test").GetAwaiter().GetResult();}catch(InvalidOperationException){failed=true;}Check(failed&&fake.Calls==2,"disabled never sends");}
        settings.Save(new JsonObject{["id"]="other",["name"]="Özel Firma",["endpoint"]="https://sms.example.invalid/send",["auth"]="bearer",["secret"]="generic-secret",["sender"]="INOKSKAR",["template"]="{\"to\":\"{phone}\",\"text\":\"{message}\"}",["successPath"]="ok",["successValue"]="true",["enabled"]=true});var custom=settings.ActiveProfile()!;Check(custom.Id.StartsWith("custom-"),"custom provider persisted");var json=SmsGateway.Expand(JsonNode.Parse(custom.Template)!,new Dictionary<string,string>{{"phone","905421234567"},{"message","Do not expand {secret}"},{"secret","NO-LEAK"}}).ToJsonString();Check(!json.Contains("NO-LEAK")&&json.Contains("{secret}"),"message cannot interpolate secret");var genericHandler=new FakeHandler{Response="{\"ok\":true}"};var genericGateway=new SmsGateway(settings,genericHandler);genericGateway.Send("5421234567","test").GetAwaiter().GetResult();Check(genericHandler.Calls==1,"custom provider request");var queue=new SmsQueue(b.Environment,b.Configuration,settings,genericGateway,protection);var job=queue.Enqueue(new[]{"5421234567","+905421234567"},"kişisel mesaj");Check(!File.ReadAllText(Path.Combine(temp,"sms-jobs.json")).Contains("kişisel mesaj"),"message encrypted");queue.StartAsync(CancellationToken.None).GetAwaiter().GetResult();var until=DateTimeOffset.UtcNow.AddSeconds(6);while(DateTimeOffset.UtcNow<until&&genericHandler.Calls<2)Thread.Sleep(50);queue.StopAsync(CancellationToken.None).GetAwaiter().GetResult();Check(genericHandler.Calls==2,"queue deduplicates recipients");settings.Save(new JsonObject{["disableOnly"]=true});Reject(()=>queue.Enqueue(new[]{"5421234567"},"test"),"inactive queue blocked");Console.WriteLine("SMS security and provider checks: PASS (isolated data; no real messages)");
    }finally{Directory.Delete(temp,true);}}
}
